with.command:
set -eu
# An inherited GH_REPO would point a call at another repository: it goes before the first gh call.
unset GH_REPO
forge_as=$(git -C "$REPO" config --get sailor.forgeAs) || { echo "sailor.forgeAs is not declared on this tree: refusing to act as the machine's active account" >&2; exit 1; }
[ -n "$forge_as" ] || { echo "sailor.forgeAs is empty on this tree: refusing to act as the machine's active account" >&2; exit 1; }
env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "$forge_as" >/dev/null || { echo "no forge token for the declared account $forge_as" >&2; exit 1; }
printf '{"login":"%s"}' "$forge_as"

set -eu
fetched=$(git -C "$REPO" fetch --no-tags "$REMOTE_NAME" "+refs/heads/$BASE:refs/remotes/$REMOTE_NAME/$BASE" "refs/tags/v*:refs/tags/v*" 2>&1) || { echo "the fetch from $REMOTE_NAME was refused: $fetched" >&2; exit 1; }
on_branch=$(git -C "$REPO" symbolic-ref --quiet --short HEAD) || { echo "the tree is on no branch: the candidate is the trunk this tree carries" >&2; exit 1; }
[ "$on_branch" = "$BASE" ] || { echo "the tree is on $on_branch, not $BASE: the candidate is the trunk this tree carries" >&2; exit 1; }
candidate=$(git -C "$REPO" rev-parse --verify "refs/heads/$BASE^{commit}")
# sailor release refuses uncommitted work in HEAD's tree: HEAD is the candidate so that refusal speaks about it.
head_now=$(git -C "$REPO" rev-parse --verify "HEAD^{commit}") || { echo "cannot read HEAD" >&2; exit 2; }
[ "$head_now" = "$candidate" ] || { echo "HEAD is not $BASE at $candidate" >&2; exit 1; }
tree_status=$(git -C "$REPO" status --porcelain --untracked-files=no) || { echo "cannot read the status of the tree, so uncommitted work cannot be ruled out" >&2; exit 2; }
[ -z "$tree_status" ] || { echo "the tree carries uncommitted changes" >&2; exit 1; }
remote=$(git -C "$REPO" rev-parse --verify --quiet "refs/remotes/$REMOTE_NAME/$BASE^{commit}") || { echo "$REMOTE_NAME has no $BASE after the fetch: a release publishes onto an existing remote trunk, and there is none to gate against" >&2; exit 1; }
git -C "$REPO" merge-base --is-ancestor "$remote" "$candidate" || { echo "the remote $BASE at $remote is not an ancestor of the candidate $candidate: publishing it would need a force" >&2; exit 1; }
tag="v$VERSION"
if tagged=$(git -C "$REPO" rev-parse --verify --quiet "refs/tags/$tag^{commit}"); then
    [ "$tagged" = "$candidate" ] || { echo "$tag already names $tagged, not the candidate $candidate" >&2; exit 1; }
fi
previous=$(git -C "$REPO" describe --tags --abbrev=0 --match 'v*' "$candidate^" 2>/dev/null || true)
printf '{"candidate":"%s","remote_trunk":"%s","tag":"%s","previous_tag":"%s"}' "$candidate" "$remote" "$tag" "$previous"

set -eu
# The policy is the file the trunk commits, read with git: a sailor on PATH never decides who authorizes.
trusted_policy() {
    policy_commit=$(git -C "$REPO" rev-parse --verify --quiet "$TRUNK^{commit}") || { echo "the trunk $TRUNK does not exist in this tree: no trusted policy to read" >&2; exit 1; }
    policy_text=$(git -C "$REPO" show "$policy_commit:.sailor/delivery-policy.json") || { echo "$TRUNK at $policy_commit carries no .sailor/delivery-policy.json" >&2; exit 1; }
    printf '%s' "$policy_text" | POLICY_COMMIT="$policy_commit" python3 -c '
import json, os, sys
def no_constant(name):
    raise ValueError("%s is not JSON" % name)
try:
    policy = json.loads(sys.stdin.read(), parse_constant=no_constant)
except ValueError as error:
    sys.exit("the delivery policy is not JSON: %s" % error)
if not isinstance(policy, dict):
    sys.exit("the delivery policy is not an object")
lines = []
for field in ("merge", "push", "release"):
    if policy.get(field) not in ("auto", "ask"):
        sys.exit("the delivery policy does not say auto or ask for %s" % field)
    lines.append("%s: %s" % (field, policy[field]))
lines.append(os.environ["POLICY_COMMIT"])
print("\n".join(lines))
'
}
cd "$REPO"
trusted_scan() {
    git -C "$REPO" show "$TRUNK:scripts/privacy-scan.sh" 2>/dev/null | cmp -s - "$REPO/scripts/privacy-scan.sh" || { echo "scripts/privacy-scan.sh in this tree differs from the one the trusted trunk commits: the gate refuses to judge with it" >&2; exit 2; }
}
trusted_scan
policy_now=$(trusted_policy) || exit 1
policy_was=$(printf '%s' "$POLICY_READ" | python3 -c 'import json,sys; p=json.load(sys.stdin); print("merge: %s\npush: %s\nrelease: %s\n%s" % (p["merge"], p["push"], p["release"], p["read_from"]))')
[ "$policy_now" = "$policy_was" ] || { echo "the delivery policy changed since it was read: the authorization in flight no longer holds; run the flow again" >&2; exit 1; }
set +e
if [ -n "$SCAN_BASE" ]; then "$REPO/scripts/privacy-scan.sh" "$REF" "$SCAN_BASE" >&2; else "$REPO/scripts/privacy-scan.sh" "$REF" >&2; fi
code=$?
set -e
[ "$code" -eq 0 ] || { echo "publication gate: privacy-scan exited $code on $REF; nothing leaves" >&2; exit "$code"; }
printf '{"ref":"%s","privacy_exit":0}' "$REF"

set -eu
# Every sailor this command runs is the copy the flow verified, checked again right before it runs.
trusted_sailor() {
    sailor_now=$(shasum -a 256 < "$SAILOR_BIN") || { echo "cannot read the trusted sailor at $SAILOR_BIN" >&2; exit 2; }
    [ "${sailor_now%% *}" = "$SAILOR_SHA" ] || { echo "the sailor at $SAILOR_BIN changed since the flow verified it: sha256 ${sailor_now%% *}, not $SAILOR_SHA" >&2; exit 2; }
    "$SAILOR_BIN" "$@"
}
cd "$REPO"
# The sailor in service builds a detached checkout of exactly the candidate and installs it; it publishes nothing.
export SAILOR_SOURCES="$REPO"
set +e
trusted_sailor release sailor --no-push --candidate "$CANDIDATE" >&2
released=$?
set -e
case "$released" in
    0) ;;
    4) echo "sailor release installed the candidate and warns that the name sailor on PATH finds another copy; this flow calls $SAILOR_BIN and never that name" >&2 ;;
    *) echo "sailor release exited $released" >&2; exit "$released" ;;
esac
printf '{"built_from":"%s"}' "$CANDIDATE"

set -eu
home=${SAILOR_HOME:-${XDG_CONFIG_HOME:-$HOME/.config}/sailor}
stamp=$(awk 'NF && $1 !~ /^#/ { print $1; exit }' "$home/state/sailor-binary-commit" 2>/dev/null || true)
[ "$stamp" = "$CANDIDATE" ] || { echo "the release stamp names ${stamp:-nothing}, not the candidate $CANDIDATE: the binary in service was built from something else" >&2; exit 1; }
[ -r "$home/bin/sailor" ] || { echo "no installed binary at the release's safe copy" >&2; exit 1; }
digest=$(shasum -a 256 < "$home/bin/sailor" | awk '{ print $1 }')
recorded=$(awk 'NF && $1 !~ /^#/ { print $1; exit }' "$home/state/sailor-binary-commit.sha256" 2>/dev/null || true)
[ -n "$recorded" ] && [ "$recorded" = "$digest" ] || { echo "bin/sailor has sha256 $digest, and the release recorded ${recorded:-nothing} for the candidate: the binary in service is not the one it built" >&2; exit 1; }
# The digest above belongs to this file; a sailor found first on PATH is another binary.
binary="$home/bin/sailor"
said=$("$binary" version) || { echo "the installed binary $binary did not answer version" >&2; exit 1; }
case "$said " in "sailor $VERSION "*) ;; *) echo "the installed binary $binary says «${said}», not sailor ${VERSION}" >&2; exit 1 ;; esac
printf '{"said":"%s","binary":"%s","commit":"%s","binary_sha256":"%s"}' "$said" "$binary" "$stamp" "$digest"

set -eu
# The policy is the file the trunk commits, read with git: a sailor on PATH never decides who authorizes.
trusted_policy() {
    policy_commit=$(git -C "$REPO" rev-parse --verify --quiet "$TRUNK^{commit}") || { echo "the trunk $TRUNK does not exist in this tree: no trusted policy to read" >&2; exit 1; }
    policy_text=$(git -C "$REPO" show "$policy_commit:.sailor/delivery-policy.json") || { echo "$TRUNK at $policy_commit carries no .sailor/delivery-policy.json" >&2; exit 1; }
    printf '%s' "$policy_text" | POLICY_COMMIT="$policy_commit" python3 -c '
import json, os, sys
def no_constant(name):
    raise ValueError("%s is not JSON" % name)
try:
    policy = json.loads(sys.stdin.read(), parse_constant=no_constant)
except ValueError as error:
    sys.exit("the delivery policy is not JSON: %s" % error)
if not isinstance(policy, dict):
    sys.exit("the delivery policy is not an object")
lines = []
for field in ("merge", "push", "release"):
    if policy.get(field) not in ("auto", "ask"):
        sys.exit("the delivery policy does not say auto or ask for %s" % field)
    lines.append("%s: %s" % (field, policy[field]))
lines.append(os.environ["POLICY_COMMIT"])
print("\n".join(lines))
'
}
cd "$REPO"
trusted_scan() {
    git -C "$REPO" show "$TRUNK:scripts/privacy-scan.sh" 2>/dev/null | cmp -s - "$REPO/scripts/privacy-scan.sh" || { echo "scripts/privacy-scan.sh in this tree differs from the one the trusted trunk commits: the gate refuses to judge with it" >&2; exit 2; }
}
trusted_scan
policy_now=$(trusted_policy) || exit 1
policy_was=$(printf '%s' "$POLICY_READ" | python3 -c 'import json,sys; p=json.load(sys.stdin); print("merge: %s\npush: %s\nrelease: %s\n%s" % (p["merge"], p["push"], p["release"], p["read_from"]))')
[ "$policy_now" = "$policy_was" ] || { echo "the delivery policy changed since it was read: the authorization in flight no longer holds; run the flow again" >&2; exit 1; }
home=${SAILOR_HOME:-${XDG_CONFIG_HOME:-$HOME/.config}/sailor}
stamp=$(awk 'NF && $1 !~ /^#/ { print $1; exit }' "$home/state/sailor-binary-commit" 2>/dev/null || true)
[ "$stamp" = "$REF" ] || { echo "the release stamp names ${stamp:-nothing}, not the candidate $REF: the binary in service was built from something else" >&2; exit 1; }
[ -r "$home/bin/sailor" ] || { echo "no installed binary at the safe copy" >&2; exit 1; }
digest=$(shasum -a 256 < "$home/bin/sailor" | awk '{ print $1 }')
recorded=$(awk 'NF && $1 !~ /^#/ { print $1; exit }' "$home/state/sailor-binary-commit.sha256" 2>/dev/null || true)
[ -n "$recorded" ] && [ "$recorded" = "$digest" ] || { echo "bin/sailor has sha256 $digest, and the release recorded ${recorded:-nothing} for the candidate: the binary in service is not the one it built" >&2; exit 1; }
[ "$digest" = "$DIGEST" ] || { echo "the binary in service changed after the journey" >&2; exit 1; }
git fetch -q --no-tags "$REMOTE_NAME"
remote_now=$(git rev-parse --verify --quiet "refs/remotes/$REMOTE_NAME/$BASE^{commit}" || true)
[ "$remote_now" = "$REMOTE_WAS" ] || { echo "the remote $BASE moved from ${REMOTE_WAS:-nothing} to ${remote_now:-nothing} during acceptance: run the release again" >&2; exit 1; }
set +e
if [ -n "$SCAN_BASE" ]; then "$REPO/scripts/privacy-scan.sh" "$REF" "$SCAN_BASE" >&2; else "$REPO/scripts/privacy-scan.sh" "$REF" >&2; fi
code=$?
set -e
[ "$code" -eq 0 ] || { echo "publication gate: privacy-scan exited $code on $REF; nothing leaves" >&2; exit "$code"; }
printf '{"ref":"%s","privacy_exit":0}' "$REF"

set -eu
# git ls-remote's own exit is checked before its answer is read: a lost transport is not an empty ref.
read_remote_ref() {
    listed=$(git -C "$REPO" ls-remote "$REMOTE_NAME" "$1") || { code=$?; echo "cannot read $1 on $REMOTE_NAME: git ls-remote exited $code, so nothing is decided on an empty answer" >&2; exit 2; }
    printf '%s\n' "$listed" | awk -v ref="$1" '$2 == ref { print $1 }'
}
upstream_remote=$(git -C "$REPO" config --get "branch.$BASE.remote") || { echo "$BASE declares no upstream remote: this flow pushes the trunk only to the upstream it declares" >&2; exit 1; }
upstream_merge=$(git -C "$REPO" config --get "branch.$BASE.merge") || { echo "$BASE declares no upstream branch: this flow pushes the trunk only to the upstream it declares" >&2; exit 1; }
[ "$upstream_remote" = "$REMOTE_NAME" ] && [ "$upstream_merge" = "refs/heads/$BASE" ] || { echo "$BASE does not track $REMOTE_NAME/$BASE: this flow pushes the trunk only to the upstream it declares" >&2; exit 1; }
remote_url=$(git -C "$REPO" remote get-url "$REMOTE_NAME") || { echo "the tree has no remote named $REMOTE_NAME" >&2; exit 2; }
case "$remote_url" in
    https://*)
        push_as_declared=$(git -C "$REPO" config --get sailor.pushAs) || { echo "sailor.pushAs is not declared: the trunk would be pushed with the machine's own credentials" >&2; exit 1; }
        secret_declared=$(git -C "$REPO" config --get sailor.pushSecretFrom) || { echo "sailor.pushSecretFrom is not declared: the trunk would be pushed with the machine's own credentials" >&2; exit 1; }
        [ -n "$push_as_declared" ] && [ -n "$secret_declared" ] || { echo "sailor.pushAs or sailor.pushSecretFrom is empty: the trunk would be pushed with the machine's own credentials" >&2; exit 1; } ;;
esac
url=$(git -C "$REPO" remote get-url "$REMOTE_NAME") || { echo "the tree has no remote named $REMOTE_NAME" >&2; exit 1; }
set -- -C "$REPO"
case "$url" in
    /*|file://*) ;;
    http://*|https://*)
        push_as=$(git -C "$REPO" config --get sailor.pushAs) || { echo "sailor.pushAs is not declared on this tree: refusing to push with the machine's own credentials" >&2; exit 1; }
        [ -n "$push_as" ] || { echo "sailor.pushAs is empty on this tree: refusing to push with the machine's own credentials" >&2; exit 1; }
        helper='!f() { printf "%s\\n" username=x-access-token; printf "password=%s\\n" "$(env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "'"$push_as"'")"; }; f'
        set -- -C "$REPO" -c credential.helper= -c "credential.helper=$helper" ;;
    *) echo "$REMOTE_NAME is $url: a push over it cannot be bound to sailor.pushAs, so this flow refuses it" >&2; exit 1 ;;
esac
remote=$(read_remote_ref "refs/heads/$BASE")
[ "$remote" = "$REMOTE_WAS" ] || { echo "the remote $BASE reads ${remote:-nothing}, not ${REMOTE_WAS:-nothing} as gated: nothing is pushed" >&2; exit 1; }
# The lease closes the window between that read and the push.
git "$@" push --force-with-lease="refs/heads/$BASE:$REMOTE_WAS" "$REMOTE_NAME" "$CANDIDATE:refs/heads/$BASE" >&2
printf '{"pushed":"%s"}' "$CANDIDATE"

set -eu
# git ls-remote's own exit is checked before its answer is read: a lost transport is not an empty ref.
read_remote_ref() {
    listed=$(git -C "$REPO" ls-remote origin "$1") || { code=$?; echo "cannot read $1 on origin: git ls-remote exited $code, so nothing is decided on an empty answer" >&2; exit 2; }
    printf '%s\n' "$listed" | awk -v ref="$1" '$2 == ref { print $1 }'
}
remote=$(read_remote_ref "refs/heads/$BASE")
[ "$remote" = "$CANDIDATE" ] || { echo "the remote $BASE reads ${remote:-nothing}, not the candidate $CANDIDATE" >&2; exit 1; }
printf '{"remote_trunk":"%s"}' "$remote"

set -eu
cd "$REPO"
trusted_scan() {
    git -C "$REPO" show "$TRUNK:scripts/privacy-scan.sh" 2>/dev/null | cmp -s - "$REPO/scripts/privacy-scan.sh" || { echo "scripts/privacy-scan.sh in this tree differs from the one the trusted trunk commits: the gate refuses to judge with it" >&2; exit 2; }
}
trusted_scan
set +e
"$REPO/scripts/privacy-scan.sh" --text "$TEXT_FILE" >&2
code=$?
set -e
[ "$code" -eq 0 ] || { echo "publication gate: privacy-scan --text exited $code on $TEXT_FILE; the text does not leave" >&2; exit "$code"; }
sha=$(shasum -a 256 < "$TEXT_FILE" | awk '{ print $1 }')
printf '{"text_file":"%s","sha256":"%s","privacy_exit":0}' "$TEXT_FILE" "$sha"

set -eu
# git ls-remote's own exit is checked before its answer is read: a lost transport is not an empty ref.
read_remote_ref() {
    listed=$(git -C "$REPO" ls-remote "$REMOTE_NAME" "$1") || { code=$?; echo "cannot read $1 on $REMOTE_NAME: git ls-remote exited $code, so nothing is decided on an empty answer" >&2; exit 2; }
    printf '%s\n' "$listed" | awk -v ref="$1" '$2 == ref { print $1 }'
}
url=$(git -C "$REPO" remote get-url "$REMOTE_NAME") || { echo "the tree has no remote named $REMOTE_NAME" >&2; exit 1; }
set -- -C "$REPO"
case "$url" in
    /*|file://*) ;;
    http://*|https://*)
        push_as=$(git -C "$REPO" config --get sailor.pushAs) || { echo "sailor.pushAs is not declared on this tree: refusing to push with the machine's own credentials" >&2; exit 1; }
        [ -n "$push_as" ] || { echo "sailor.pushAs is empty on this tree: refusing to push with the machine's own credentials" >&2; exit 1; }
        helper='!f() { printf "%s\\n" username=x-access-token; printf "password=%s\\n" "$(env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "'"$push_as"'")"; }; f'
        set -- -C "$REPO" -c credential.helper= -c "credential.helper=$helper" ;;
    *) echo "$REMOTE_NAME is $url: a push over it cannot be bound to sailor.pushAs, so this flow refuses it" >&2; exit 1 ;;
esac
if ! git -C "$REPO" rev-parse --verify --quiet "refs/tags/$TAG" >/dev/null; then
    git -C "$REPO" tag -a "$TAG" -m "$TAG" "$CANDIDATE"
fi
tagged=$(git -C "$REPO" rev-parse "refs/tags/$TAG^{commit}")
[ "$tagged" = "$CANDIDATE" ] || { echo "$TAG names $tagged, not $CANDIDATE" >&2; exit 1; }
object=$(git -C "$REPO" rev-parse "refs/tags/$TAG")
remote=$(read_remote_ref "refs/tags/$TAG")
if [ -z "$remote" ]; then
    git "$@" push "$REMOTE_NAME" "refs/tags/$TAG:refs/tags/$TAG" >&2
    remote=$(read_remote_ref "refs/tags/$TAG")
fi
[ "$remote" = "$object" ] || { echo "the remote $TAG reads ${remote:-nothing}, not $object" >&2; exit 1; }
printf '{"tag":"%s","commit":"%s"}' "$TAG" "$tagged"

set -eu
cd "$REPO"
# An inherited GH_REPO would point a call at another repository: it goes before the first gh call.
unset GH_REPO
forge_as=$(git -C "$REPO" config --get sailor.forgeAs) || { echo "sailor.forgeAs is not declared on this tree: refusing to act as the machine's active account" >&2; exit 1; }
[ -n "$forge_as" ] || { echo "sailor.forgeAs is empty on this tree: refusing to act as the machine's active account" >&2; exit 1; }
env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "$forge_as" >/dev/null || { echo "no forge token for the declared account $forge_as" >&2; exit 1; }
[ -z "${FORGE_REPO:-}" ] || export GH_REPO="$FORGE_REPO"
# An empty --user or an empty GH_TOKEN makes gh answer as the machine's active account.
forge() {
    who=$(git -C "$REPO" config --get sailor.forgeAs) && [ -n "$who" ] || { echo "sailor.forgeAs vanished from this tree: refusing" >&2; exit 1; }
    token=$(env -u GH_TOKEN -u GITHUB_TOKEN -u GH_REPO gh auth token --user "$who") && [ -n "$token" ] || { echo "no forge token for $who: refusing" >&2; exit 1; }
    if [ -n "${FORGE_REPO:-}" ]; then
        env -u GITHUB_TOKEN -u GH_ENTERPRISE_TOKEN -u GITHUB_ENTERPRISE_TOKEN GH_REPO="$FORGE_REPO" GH_TOKEN="$token" gh "$@"
    else
        env -u GITHUB_TOKEN -u GH_ENTERPRISE_TOKEN -u GITHUB_ENTERPRISE_TOKEN -u GH_REPO GH_TOKEN="$token" gh "$@"
    fi
}
text_now=$(shasum -a 256 < "$TEXT_FILE") || { echo "cannot read $TEXT_FILE to compare it with what the gate judged" >&2; exit 2; }
[ "${text_now%% *}" = "$TEXT_SHA" ] || { echo "$TEXT_FILE changed after the publication gate judged it: nothing leaves" >&2; exit 1; }
if ! forge release view "$TAG" --json tagName >/dev/null; then
    forge release create "$TAG" --verify-tag --title "$TAG" --notes-file "$TEXT_FILE" >&2
else
    draft=$(forge release view "$TAG" --json isDraft --jq .isDraft) || { echo "cannot read whether the release $TAG is a draft" >&2; exit 2; }
    if [ "$draft" = true ]; then
        forge release edit "$TAG" --draft=false >&2
    fi
fi
seen=$(forge release view "$TAG" --json tagName,isDraft,url --jq '[.tagName, .isDraft, .url] | @tsv') || { echo "cannot read the release $TAG on the host" >&2; exit 2; }
seen_tag=$(printf '%s' "$seen" | cut -f1) || { echo "cannot read the release answer" >&2; exit 2; }
seen_draft=$(printf '%s' "$seen" | cut -f2) || { echo "cannot read the release answer" >&2; exit 2; }
seen_url=$(printf '%s' "$seen" | cut -f3) || { echo "cannot read the release answer" >&2; exit 2; }
[ "$seen_tag" = "$TAG" ] || { echo "the host has no release for $TAG" >&2; exit 1; }
[ "$seen_draft" = false ] || { echo "the release $TAG is still a draft" >&2; exit 1; }
printf '{"tag":"%s","url":"%s"}' "$TAG" "$seen_url"
